 for arm,a in v['arms'].items():L.append(f"| {cell} | {arm} | {a['meanMs']:.3f} | {a['forkMinMs']:.3f}–{a['forkMaxMs']:.3f} | {a['firstRowMeanMs']:.3f} | {a['allocationMeanBytes']/1e6:.2f} |")
